const correctionSchema = (domain?: string) =>
  z.object({
    givenName: z.string().trim().min(1, "Enter the given name.").max(100, "Enter the given name."),
    familyName: z
      .string()
      .trim()
      .min(1, "Enter the family name.")
      .max(100, "Enter the family name."),
    contactEmail: z
